constraints:
1 <= n <= 10^{4}

expected time complexity: O(log(n) * log(n))
expected auxiliary space: O(1)

standard_solution_code:
def count_set_bits(n):
	ret = 0
	while n:
		if n & 1:
			ret += 1
		n >>= 1
	return ret

class Solution:

	def is_bleak(self, n):
		a = 0
		for j in range(14, -1, -1):
			if n > j:
				a = j
				break
		for m in range(n - a, n):
			if count_set_bits(m) + m == n:
				return 0
		return 1
